        ,"Some applications should quit.": [.traditionalChinese: "部分應用程式應該結束。", .japanese: "一部のアプリケーションを終了してください。", .korean: "일부 응용 프로그램은 종료되어야 합니다.", .russian: "Некоторые приложения должны быть закрыты."]
        ,"Some privacy items could not be removed": [.traditionalChinese: "部分隱私項目未能移除", .japanese: "一部のプライバシー項目を削除できませんでした", .korean: "일부 개인 정보 항목을 제거할 수 없습니다.", .russian: "Некоторые элементы конфиденциальности не удалось удалить."]
        ,"Sort By Size ▼": [.traditionalChinese: "依大小排序 ▼", .japanese: "サイズでソート ▼", .korean: "크기순 정렬 ▼", .russian: "Сортировка по размеру ▼"]
        ,"Sort by": [.traditionalChinese: "排序方式", .japanese: "並べ替え", .korean: "정렬 기준", .russian: "Сортировать по"]
        ,"Sort by Size": [.traditionalChinese: "依大小排序", .japanese: "サイズ順で並べ替え", .korean: "크기순 정렬", .russian: "Сортировать по размеру"]
        ,"Sort files easily": [.traditionalChinese: "輕鬆排列檔案", .japanese: "ファイルを簡単に並べ替え", .korean: "파일을 쉽게 정렬", .russian: "Легкая сортировка файлов"]
        ,"Spot file dumps": [.traditionalChinese: "發現檔案堆積", .japanese: "ファイルのダンプを特定", .korean: "파일 덤프 찾기", .russian: "Найти свалки файлов"]
        ,"Start": [.traditionalChinese: "開始", .japanese: "開始", .korean: "시작", .russian: "Начать"]
        ,"Start Scan": [.traditionalChinese: "開始掃描", .japanese: "スキャンを開始", .korean: "검사 시작", .russian: "Начать сканирование"]
        ,"Start a comprehensive and thorough scan of your Mac.": [.traditionalChinese: "開始全面且徹底地掃描您的 Mac。", .japanese: "Macの包括的で徹底的なスキャンを開始します。", .korean: "Mac의 포괄적이고 철저한 스캔을 시작합니다.", .russian: "Запустите комплексное и тщательное сканирование Mac."]
        ,"Stopping": [.traditionalChinese: "正在停止", .japanese: "停止中", .korean: "중지 중", .russian: "Остановка"]
