        ,"Unable to get space info": [.traditionalChinese: "無法取得空間資訊", .japanese: "空き容量情報を取得できません", .korean: "공간 정보를 가져올 수 없음", .russian: "Не удалось получить информацию о месте"]
        ,"Update Now": [.traditionalChinese: "立即更新", .japanese: "今すぐアップデート", .korean: "지금 업데이트", .russian: "Обновить сейчас"]
        ,"Updates available": [.traditionalChinese: "有可用更新", .japanese: "アップデートあり", .korean: "업데이트 가능", .russian: "Доступны обновления"]
        ,"Used \\(ByteCountFormatter.string(fromByteCount: usedDiskSpace, countStyle: .file))": [.traditionalChinese: "已使用 \\(ByteCountFormatter.string(fromByteCount: usedDiskSpace, countStyle: .file))", .japanese: "\\(ByteCountFormatter.string(fromByteCount: usedDiskSpace, countStyle: .file)) 使用済み", .korean: "\\(ByteCountFormatter.string(fromByteCount: usedDiskSpace, countStyle: .file)) 사용됨", .russian: "Использовано \\(ByteCountFormatter.string(fromByteCount: usedDiskSpace, countStyle: .file))"]
